import json
from pathlib import Path
p=Path(__file__).with_name('assembly_laidlaw.json')
d=json.loads(p.read_text())
d['result']='Reversed and remanded, 7–2; district penalty judgment returned to ordinary unresolved appellate review.'
d['lead_support']=['Stone-Zsela','Stevens',"O'Connor",'Kennedy','Souter','Ginsburg','Breyer']
d['annex_files']=['OT_1999CHUNK1_LAIDLAW_REMEDY_CLARIFICATION.md']
d['form']=d['form'].replace('the exact remand effect remains subject to the authorized clarification.','the clarified common remand removes the appellate vacatur without finally approving or ordering collection of the penalty.')
d['compatibility']="Stone and the six remand Associates support the same clarified reversal, ordinary restoration and unresolved appellate review. The separate non-Stone §8 audit expressly corrects imprecise vacatur terminology and disclaims continuing vacatur; no remedial split remains. Stevens joins the common sufficient grounds while separately advancing A5. Scalia and Thomas reject standing and independently reject factual deterrent redress; their hypothetical mootness agreement supplies no operative remand vote. No additional circulation history or new substantive ground is invented."
d['stone']=d['stone'].replace('The exact compatibility with the frozen common remand is pending clarification, not silently revised.','The separately frozen remedy audit establishes full compatibility: restoration means the existing judgment is operative in ordinary unresolved review, without final merits approval, immediate collection or a special stay.')
d['continuity']=d['continuity'].replace('Exact immediate judgment effect is pending clarification.','The district penalty judgment returns to unresolved appellate review under ordinary mandate and applicable stay rules.')
d['blocks']['Public Action']="The Court reverses the Fourth Circuit's judgment and remands for proceedings consistent with its standing, deterrent-redress and voluntary-cessation holdings."
d['blocks']['Judgment & Remedy']="Reversed and remanded, 7–2. Supporting: Stone-Zsela, Stevens, O'Connor, Kennedy, Souter, Ginsburg, and Breyer. Opposing: Scalia and Thomas, who would direct jurisdictional dismissal. The appellate vacatur and dismissal direction are set aside. The district penalty judgment returns to ordinary appellate review, subject to the unresolved issues and applicable stay procedures; this disposition does not affirm its merits or amount. No immediate collection order, new injunction, fee award or special stay is entered."
d['blocks']['Procedure After Action']="The Fourth Circuit must address the remaining appeal and cross-appeal under the holdings stated here, including supported closure and recurrence facts, the preserved diligent-prosecution defense and remaining penalty questions. The district judgment returns to unresolved ordinary appellate status when reversal takes effect through the usual appellate process. No prior mandate, implementing dismissal, execution stay or bond is presumed. Collection remains governed by ordinary mandate and applicable stay rules; the Court orders neither immediate execution nor a new stay. The fee-petition timing stay supplies no independent jurisdiction or fee award."
p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
print('Laidlaw common remedy draft now matches final non-Stone audit and Stone core; no Record written.')
